1	import { randomUUID } from "node:crypto";
2	import express from "express";
3	import { exchangeRefreshToken, parseCookies } from "./auth.js";
4	
5	const REDIRECT_URI = "http://127.0.0.1:3000/callback";
6	const FRONTEND_URL = "http://127.0.0.1:5173";
7	
8	export function createApp({ clientId, clientSecret }) {
9	  const app = express();
10	
11	  // sessionId -> { refreshToken }. In-memory: a server restart clears sessions
12	  // (re-login), which is acceptable for local dev. Swap for a real store later.
13	  const sessions = new Map();
14	
15	  app.get("/callback", async (req, res) => {
16	    const { code, error } = req.query;
17	    console.info("[server] OAuth callback received");
18	
19	    if (error || !code) {
20	      return res.redirect(`${FRONTEND_URL}?error=access_denied`);
21	    }
22	
23	    const credentials = Buffer.from(`${clientId}:${clientSecret}`).toString(
24	      "base64",
25	    );
26	
27	    let tokenResponse;
28	    try {
29	      tokenResponse = await fetch("https://accounts.spotify.com/api/token", {
30	        method: "POST",
31	        headers: {
32	          Authorization: `Basic ${credentials}`,
33	          "Content-Type": "application/x-www-form-urlencoded",
34	        },
35	        body: new URLSearchParams({
36	          grant_type: "authorization_code",
37	          code,
38	          redirect_uri: REDIRECT_URI,
39	        }),
40	      });
41	    } catch (err) {
42	      console.error("[server] token exchange network error:", err.message);
43	      return res.redirect(`${FRONTEND_URL}?error=token_exchange_failed`);
44	    }
45	
46	    if (!tokenResponse.ok) {
47	      console.error("[server] token exchange failed:", tokenResponse.status);
48	      return res.redirect(`${FRONTEND_URL}?error=token_exchange_failed`);
49	    }
50	
51	    let refreshToken;
52	    try {
53	      const body = await tokenResponse.json();
54	      refreshToken = body.refresh_token;
55	      if (!refreshToken) {
56	        return res.redirect(`${FRONTEND_URL}?error=token_exchange_failed`);
57	      }
58	    } catch (err) {
59	      console.error("[server] failed to parse token response:", err.message);
60	      return res.redirect(`${FRONTEND_URL}?error=token_exchange_failed`);
61	    }
62	
63	    const sessionId = randomUUID();
64	    sessions.set(sessionId, { refreshToken });
65	    console.info(`[server] session created (${sessions.size} active)`);
66	
67	    res.cookie("sid", sessionId, {
68	      httpOnly: true,
69	      sameSite: "lax",
70	      secure: false, // http on localhost/127.0.0.1
71	      path: "/",
72	      maxAge: 30 * 24 * 60 * 60 * 1000,
73	    });
74	
75	    // No token in the URL — the SPA fetches one via POST /api/refresh.
76	    res.redirect(FRONTEND_URL);
77	  });
78	
79	  app.post("/api/refresh", async (req, res) => {
80	    const { sid } = parseCookies(req.headers.cookie);
81	    const session = sid ? sessions.get(sid) : undefined;
82	    console.info("[server] token refresh requested");
83	    if (!session) {
84	      return res.status(401).json({ error: "no_session" });
85	    }
86	
87	    try {
88	      const { accessToken, expiresIn, refreshToken } =
89	        await exchangeRefreshToken(session.refreshToken, {
90	          clientId,
91	          clientSecret,
92	        });
93	      session.refreshToken = refreshToken; // persist Spotify rotation
94	      console.info("[server] token refresh succeeded");
95	      res.json({ access_token: accessToken, expires_in: expiresIn });
96	    } catch (err) {
97	      console.error(
98	        "[server] token refresh failed, session evicted:",
99	        err.message,
100	      );
101	      sessions.delete(sid);
102	      res.status(401).json({ error: "refresh_failed" });
103	    }
104	  });
105	
106	  return { app, sessions };
107	}
